import React, { useEffect, useState } from 'react';
import axios from 'axios';
import Swal from 'sweetalert2';
import 'bootstrap/dist/css/bootstrap.min.css';
import './campanas.css';
import config from './config';

function App() {
  const [campaigns, setCampaigns] = useState([]);
  const [encryptedId, setEncryptedId] = useState('');

  useEffect(() => {
    const fetchData = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'No estás autenticado. Por favor, inicia sesión.',
        }).then(() => {
          localStorage.removeItem('token'); 
          window.location.href = '/';
        });
        return;
      }

      const urlParams = new URLSearchParams(window.location.search);
      const encryptedIdFromUrl = urlParams.get('id');

      if (!encryptedIdFromUrl) {
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'No se pudieron obtener los parámetros.',
        }).then(() => {
          localStorage.removeItem('token'); 
          window.location.href = '/';
        });
        return;
      }

      setEncryptedId(encryptedIdFromUrl);

      try {
        const decryptResponse = await axios.post(
          `${config.API_BASE_URL}/decrypt`,
          { encrypted_value: encryptedIdFromUrl },
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        const userId = decryptResponse.data.decrypted_value;

        const campaignsResponse = await axios.get(
          `${config.API_BASE_URL}/campanas/${userId}`,
          {
            headers: {
              Authorization: `Bearer ${token}`, // Incluye el token JWT en la cabecera
            },
          }
        );
        

        const campaignsData = campaignsResponse.data;

        const campaignsWithEncryption = await Promise.all(
          campaignsData.map(async (campaign) => {
            if (campaign.estado) {
              const encryptResponse = await axios.post(
                `${config.API_BASE_URL}/encrypt`,
                { value: campaign.id_campana.toString() },
                {
                  headers: {
                    Authorization: `Bearer ${token}`,
                  },
                }
              );
              return {
                ...campaign,
                encryptedCampaignId: encryptResponse.data.encrypted_value,
              };
            }
            return null;
          })
        );

        setCampaigns(campaignsWithEncryption.filter(Boolean));
      } catch (error) {
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'Hubo un problema al cargar los datos.',
        }).then(() => {
          localStorage.removeItem('token'); 
          window.location.href = '/';
        });
      }
    };

    fetchData();
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token'); // Eliminar token del localStorage al cerrar sesión
    window.location.href = '/';
  };

  const handleCampaignClick = (encryptedCampaignId) => {
    window.location.href = `modulos?id=${encryptedId}&campana=${encryptedCampaignId}`;
  };

  const handleRegisterModule = () => {
    window.location.href = `registrar_modulo?id=${encryptedId}`;
  };
  

  return (
    <div>
      <div className="container mt-5">
        <div className="card">
        <div className="card-header d-flex justify-content-between align-items-center">
          <h1 className="h3">Campañas</h1>
          <div>
            {/*<button className="btn btn-primary me-2" onClick={() => handleRegisterModule()}>
              Registrar Campaña
            </button>*/}
            <button className="btn btn-danger" onClick={handleLogout}>
              Cerrar Sesión
            </button>
          </div>
        </div>

          <div className="card-body">
            <p className="text-center">Selecciona una campaña</p>
            <div className="row row-cols-1 row-cols-md-2 g-4">
              {campaigns.map((campaign) => (
                <div className="col" key={campaign.id_campana}>
                  <div className="card h-100">
                    <button
                      className="btn btn-light btn-campaign d-flex align-items-center"
                      onClick={() => handleCampaignClick(campaign.encryptedCampaignId)}
                    >
                      <img
                        src={`data:image/png;base64,${campaign.imagen}`}
                        alt={campaign.nombre}
                      />
                      <span>{campaign.nombre}</span>
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
